        XCTAssertTrue(kuruma.waitForExistence(timeout: 5))

        var beforeFrames: [String: CGRect] = [:]
        for name in ["くるま", "電車", "新幹線", "飛行機", "歩き"] {
            beforeFrames[name] = app.buttons[name].frame
