5	final class SentenceViewModel {
6	    private(set) var cards: [PictureCard] = []
7	
8	    var isEmpty: Bool { cards.isEmpty }
9	
10	    func append(_ card: PictureCard) {
11	        cards.append(card)
12	    }
13	
14	    func remove(at index: Int) {
15	        guard cards.indices.contains(index) else { return }
16	        cards.remove(at: index)
17	    }
18	
19	    func move(from source: Int, to destination: Int) {
20	        guard cards.indices.contains(source) else { return }
21	        let dest = min(max(destination, 0), cards.count)
22	        let card = cards.remove(at: source)
23	        cards.insert(card, at: dest > source ? dest - 1 : dest)
24	    }
