import SwiftUI

struct SentenceAreaView: View {
    var sentenceVM: SentenceViewModel
    let ttsService: TTSService

    var body: some View {
        HStack(spacing: 8) {
            PlaybackButtonView(
                isSpeaking: ttsService.isSpeaking,
                onTap: {
                    if ttsService.isSpeaking {
                        ttsService.stop()
                    } else {
                        let text = sentenceVM.fullKanaText()
                        ttsService.speak(text)
                    }
                }
            )
            .disabled(sentenceVM.isEmpty)
            .opacity(sentenceVM.isEmpty ? 0.4 : 1.0)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(Array(sentenceVM.cards.enumerated()), id: \.element.id) { index, card in
                        SentenceCardView(card: card) {
                            withAnimation(.easeInOut(duration: 0.2)) {
                                sentenceVM.remove(at: index)
                            }
                        }
                        .draggable(card.id.uuidString) {
                            SentenceCardView(card: card, onRemove: {})
                                .opacity(0.8)
                        }
                        .dropDestination(for: String.self) { items, _ in
                            guard let idString = items.first,
                                  let sourceIndex = sentenceVM.cards.firstIndex(where: { $0.id.uuidString == idString }) else {
                                return false
                            }
                            withAnimation(.easeInOut(duration: 0.2)) {
                                sentenceVM.move(from: sourceIndex, to: index)
                            }
                            return true
                        }
                    }
                }
                .padding(.vertical, 4)
            }

            if !sentenceVM.isEmpty {
                Button {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        sentenceVM.clear()
                    }
                } label: {
                    Image(systemName: "trash")
                        .font(.title3)
                        .foregroundStyle(.red)
                }
                .accessibilityLabel("すべて消す")
            }
        }
        .padding(.horizontal, 12)
        .frame(height: Constants.sentenceAreaHeight)
        .background(Constants.Colors.sentenceAreaBackground)
    }
}

import SwiftUI

struct SentenceCardView: View {
    let card: PictureCard
    let onRemove: () -> Void

    var body: some View {
        Button(action: onRemove) {
            VStack(spacing: 2) {
                CardImageView(card: card)
                    .frame(width: 44, height: 44)
                    .clipShape(RoundedRectangle(cornerRadius: 6))

                Text(card.displayName)
                    .font(.caption2)
                    .fontWeight(.medium)
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)
            }
            .padding(4)
            .frame(width: 60, height: 70)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(categoryColor(for: card.category).opacity(0.15))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(categoryColor(for: card.category), lineWidth: 1.5)
            )
        }
        .buttonStyle(.plain)
        .accessibilityLabel("\(card.displayName)を削除")
    }
}

func categoryColor(for category: String) -> Color {
    switch category {
    case "場所": return .blue
    case "動作": return .orange
    case "気持ち": return .pink
    case "食べ物": return .green
    case "人": return .purple
    case "生活": return .teal
    case "いつ": return .indigo
    case "手段": return .brown
    default: return .gray
    }
}

